import { DISCOUNT_CODES } from "./codes.js";

/** Fraction of the subtotal the customer pays after the code is applied. */
export function discountMultiplier(code) {
  if (!code) return 1;
  const percent = DISCOUNT_CODES[code];
  if (percent === undefined) return 1;
  return percent / 100;
}

